class Solution { public int divide(int x,int y) { boolean neg=(x<0)^(y<0);long a=Math.abs((long)x),b=Math.abs((long)y),q=0;for(int i=31;i>=0;i--)if((a>>i)>=b){a-=b<<i;q|=1L<<i;}if(neg)q=-q;if(q>Integer.MAX_VALUE)return Integer.MAX_VALUE;if(q<Integer.MIN_VALUE)return Integer.MIN_VALUE;return (int)q;} }
